/// <summary>
/// The data contract for a <c>METSalesOrderConfirmedBusinessEvent</c>.
/// </summary>
[DataContract]
public final class METSalesOrderConfirmedBusinessEventContract extends BusinessEventsContract
{
    private CustInvoiceAccount orderAccount;
    private ConfirmId   confirmId;
    private METSalesOrderTypeID   salesOrderType;
    private date        salesOrderDate;
    private date        webOrderDate;
    private VendInvoiceId invoiceId;
    private SalesId salesId;
    private CurrencyCode currencyCode;
    private AmountCur   confirmAmount;
    private TransDate confirmDate;
    private TransDate invoiceDate;
    private DueDate invoiceDueDate;
    private AmountMST invoiceAmount;
    private LegalEntityDataAreaId legalEntity;
    private CustRef customerReference;
    private METPromotionId promotionId;
    private METDeliveryInstructions deliveryInstructions;
    private SalesShippingDateRequested requestedShippingDate;
    private METIndustryKey  industryKey;
    private LogisticsAddressStreet deliveryAddressStreet;
    private LogisticsAddressCityName deliveryAddressCity;
    private LogisticsAddressStateId  deliveryAddressStateId;
    private LogisticsAddressZipCodeId deliveryAddressPostcode;
    private LogisticsDeliveryName deliveryName;
    private InventSiteId shippingSiteId;
    private DimensionDisplayValue   dimensionDisplayValue;
    private SalesStatus salesStatus;


}

Method.Source:
    /// <summary>
    /// Creates a <c>METSalesOrderConfirmedBusinessEventContract</c> from a <c>CustConfirmJour</c> record.
    /// </summary>
    /// <param name = "_custConfirmJour">A <c>CustConfirmJour</c> record.</param>
    /// <returns>A <c>SalesInvoicePostedBusinessEventContract</c>.</returns>
    public static METSalesOrderConfirmedBusinessEventContract newFromCustConfirmJour(CustConfirmJour _custConfirmJour)
    {
        var contract = new METSalesOrderConfirmedBusinessEventContract();
        contract.initialize(_custConfirmJour);

        return contract;
    }

    private void initialize(CustConfirmJour _custConfirmJour)
    {
        METSalesTable   metSalesTable;
        SalesTable      salesTable;
        LogisticsPostalAddress  logisticsPostalAddress;

        salesId = _custConfirmJour.SalesId;

        select firstonly salesTable
            join OrderDateTime, PromotionId, DeliveryInstructions from metSalesTable
            where salesTable.SalesId == salesId
               && metSalesTable.SalesTable == salesTable.RecId;

        logisticsPostalAddress = salesTable.deliveryAddress();

        orderAccount = salesTable.CustAccount;
        confirmId = _custConfirmJour.ConfirmId;
        currencyCode = _custConfirmJour.CurrencyCode;
        confirmAmount = _custConfirmJour.ConfirmAmount;
        confirmDate = _custConfirmJour.ConfirmDate;
        legalEntity = _custConfirmJour.DataAreaId;
        industryKey = METCustTable::find(_custConfirmJour.OrderAccount).IndustryKey;
        salesOrderDate = salesTable.createDate();
        customerReference = salesTable.CustomerRef;
        webOrderDate = DateTimeUtil::date(metSalesTable.OrderDateTime);
        promotionId = metSalesTable.PromotionId;
        deliveryInstructions = metSalesTable.DeliveryInstructions;
        requestedShippingDate = salesTable.ShippingDateRequested;
        shippingSiteId = salesTable.InventSiteId;
        deliveryName = salesTable.DeliveryName;
        salesStatus = salesTable.SalesStatus;
        salesOrderType = salesTable.METSalesOrderType;
        dimensionDisplayValue = DimensionSetEntity::find(salesTable.DefaultDimension).DisplayValue;
        deliveryAddressStreet = logisticsPostalAddress.Street;
        deliveryAddressCity = logisticsPostalAddress.City;
        deliveryAddressStateId = logisticsPostalAddress.State;
        deliveryAddressPostcode = logisticsPostalAddress.ZipCode;
    }

private void new()
{
}

